	bountyListItemFieldStatus                          = big.NewInt(1 << 26)
	bountyListItemFieldSubmissionsClosedAt             = big.NewInt(1 << 27)
	bountyListItemFieldTitle                           = big.NewInt(1 << 28)
	bountyListItemFieldUnresolvedSubmissionsCount      = big.NewInt(1 << 29)
